CREATE FUNCTION public.fn_auditar_saldos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.saldo <> NEW.saldo THEN
        VALUES (OLD.cuenta_id, OLD.saldo, NEW.saldo, CURRENT_USER);
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_auditar_saldos() OWNER TO postgres;

--
-- Name: fn_validar_borrado_cliente(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_validar_borrado_cliente() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM cuentas WHERE cliente_id = OLD.cliente_id AND saldo > 0) THEN
        RAISE EXCEPTION 'No se puede eliminar un cliente que posee cuentas con saldo activo.';
    END IF;
    RETURN OLD;
END;
$$;


ALTER FUNCTION public.fn_validar_borrado_cliente() OWNER TO postgres;

--
-- Name: fn_validar_dpi(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_validar_dpi() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF LENGTH(NEW.dpi) < 13 THEN
        RAISE EXCEPTION 'El documento de identificación (DPI) debe tener al menos 13 caracteres válidos.';
    END IF;
    RETURN NEW;
END;
$$;


